describe('CSV Import Functionality', () => {
    beforeEach(() => {
        cy.visit('/import'); // Navigate to the import page
    });

    it('should successfully import records from a valid CSV file', () => {
        const fileName = 'valid_records.csv';
        cy.get('input[type="file"]').attachFile(fileName); // Attach the valid CSV file
        cy.get('button.import-button').click(); // Click the import button
        cy.get('.notification').should('contain', 'Import successful'); // Verify success message
        cy.get('.records-list').should('contain', 'Record 1'); // Verify records are displayed
    });

    it('should show an error message when importing an invalid CSV file', () => {
        const fileName = 'invalid_records.csv';
        cy.get('input[type="file"]').attachFile(fileName); // Attach the invalid CSV file
        cy.get('button.import-button').click(); // Click the import button
        cy.get('.notification').should('contain', 'Import failed'); // Verify error message
        cy.get('.error-details').should('be.visible'); // Verify error details are displayed
    });
});
